<?php defined('ABSPATH') || exit; $base=home_url('/companion/');$root='dungeon-master/campaigns/'.$campaign->id().'/journal';$active=array_values(array_filter($entries??[],static fn($e):bool=>$e->status()!=='archived'));$archived=array_values(array_filter($entries??[],static fn($e):bool=>$e->status()==='archived')); ?>
<section class="gmrc-campaign-journal" aria-labelledby="gmrc-campaign-journal-title"><header class="gmrc-campaign-journal__hero"><div><p class="gmrc-dm-desk__eyebrow">Phase III.15.8 · Private DM Chronicle</p><h1 id="gmrc-campaign-journal-title">The Campaign Journal</h1><p>Keep NPCs, locations, secrets, lore and unresolved threads beside <strong><?php echo esc_html($campaign->name()); ?></strong>.</p></div><?php if(!$campaign->isArchived()): ?><a class="gmrc-journal-button" href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/create',$base)); ?>">Write New Note</a><?php endif; ?></header>
<?php if(($flash['success']??null)): ?><p class="gmrc-journal-flash" role="status"><?php echo esc_html($flash['success']); ?></p><?php endif; ?>
<nav class="gmrc-journal-summary" aria-label="Campaign Journal summary"><span><strong><?php echo count($active); ?></strong> current notes</span><span><strong><?php echo count(array_filter($active,static fn($e):bool=>$e->pinned())); ?></strong> pinned</span><span><strong><?php echo count($archived); ?></strong> archived</span></nav>
<?php if($active===[]): ?><article class="gmrc-journal-empty"><h2>The pages are waiting</h2><p>No private campaign notes have been written yet.</p></article><?php else: ?><div class="gmrc-journal-grid"><?php foreach($active as $entry): ?><article class="gmrc-journal-card <?php echo $entry->pinned()?'is-pinned':''; ?>"><div class="gmrc-journal-card__meta"><span><?php echo esc_html($entry->categoryLabel()); ?></span><span><?php echo esc_html(ucfirst($entry->status())); ?></span><?php if($entry->pinned()): ?><span>★ Pinned</span><?php endif; ?></div><h2><?php echo esc_html($entry->title()); ?></h2><p><?php echo esc_html(wp_trim_words($entry->content(),34,'…')); ?></p><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$entry->id(),$base)); ?>">Open note <span aria-hidden="true">→</span></a></article><?php endforeach; ?></div><?php endif; ?>
<?php if($archived!==[]): ?><details class="gmrc-journal-archive"><summary>Archived pages (<?php echo count($archived); ?>)</summary><div class="gmrc-journal-grid"><?php foreach($archived as $entry): ?><article class="gmrc-journal-card"><div class="gmrc-journal-card__meta"><span><?php echo esc_html($entry->categoryLabel()); ?></span><span>Archived</span></div><h2><?php echo esc_html($entry->title()); ?></h2><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$entry->id(),$base)); ?>">Read archived note</a></article><?php endforeach; ?></div></details><?php endif; ?>
<p class="gmrc-journal-back"><a href="<?php echo esc_url(add_query_arg('gmrc_route','dungeon-master/campaigns/'.$campaign->id(),$base)); ?>">← Back to Campaign Chronicle</a></p></section>
